examples.template:
NavigationStack {
    MonarchAiMemoryPanel(
        memories,
        startsSelecting: true,
        onEdit: { id, text in
            if let index = memories.firstIndex(where: { $0.id == id }) { memories[index].text = text }
        },
        onForget: { id in memories.removeAll { $0.id == id } },
        onForgetMany: { ids in memories.removeAll { ids.contains($0.id) } }
    )
    .monarchCanvas()
    .navigationTitle("Memories")
    #if os(iOS)
    .navigationBarTitleDisplayMode(.inline)
    #endif
}
.environment(\.locale, Locale(identifier: {{locale}}))
.environment(\.timeZone, TimeZone(identifier: {{timeZone}}) ?? .gmt)

